/**
 * The workspace write lock: the pure rule that decides whether a workspace is
 * read-only, and the error a refused write throws.
 *
 * A workspace is locked while its subscription is not in good standing. Only
 * writes are refused; reads, billing, notification housekeeping and Taskflow's
 * own background work stay open. `billing-service` owns the gate that applies
 * this rule to a write.
 */
import type { Subscription, WorkspaceLockReason } from "@/types/billing";
import type { IsoTimestamp, OrgId } from "@/types/common";

const LOCK_DESCRIPTIONS: Readonly<Record<WorkspaceLockReason, string>> = {
  past_due: "the subscription payment is past due",
  canceled: "the subscription has been canceled",
  trial_ended: "the trial has ended and no plan has been chosen",
};

/** Thrown by a write that is refused because the workspace is read-only. */
export class WorkspaceLockedError extends Error {
  readonly code = "plan_limit_exceeded" as const;

  constructor(
    readonly orgId: OrgId,
    readonly reason: WorkspaceLockReason,
  ) {
    super(`This workspace is read-only: ${LOCK_DESCRIPTIONS[reason]}.`);
    this.name = "WorkspaceLockedError";
  }
}

/**
 * The lock rule, evaluated against the subscription as stored. `null` means
 * the workspace is writable at `now`.
 *
 * - no subscription row, or `active`: writable
 * - `past_due`: locked straight away
 * - `trialing`: locked from the moment the period end is reached
 * - `canceled`: locked from the moment the cancellation date is reached; a
 *   cancellation scheduled for later keeps it writable until then, and a
 *   canceled subscription with no date counts as canceled now
 */
export function lockReasonFor(
  subscription: Subscription | null,
  now: Date = new Date(),
): WorkspaceLockReason | null {
  if (!subscription) return null;

  switch (subscription.status) {
    case "active":
      return null;
    case "past_due":
      return "past_due";
    case "trialing":
      return hasReached(subscription.currentPeriodEnd, now)
        ? "trial_ended"
        : null;
    case "canceled":
      if (subscription.cancelAt === null) return "canceled";
      return hasReached(subscription.cancelAt, now) ? "canceled" : null;
  }
}

function hasReached(stamp: IsoTimestamp, now: Date): boolean {
  return new Date(stamp).getTime() <= now.getTime();
}

