/**
 * The workspace write-lock rule and the error a refused write throws.
 */
import { describe, expect, it } from "vitest";

import { lockReasonFor, WorkspaceLockedError } from "@/lib/billing-lock";
import { isDomainError, toAppError } from "@/lib/errors";
import type { Subscription } from "@/types/billing";
import { toIsoTimestamp } from "@/types/common";
import type { OrgId, SubscriptionId } from "@/types/common";

const NOW = new Date("2026-06-01T12:00:00.000Z");
const EARLIER = toIsoTimestamp(new Date("2026-06-01T11:00:00.000Z"));
const LATER = toIsoTimestamp(new Date("2026-06-01T13:00:00.000Z"));
const ORG_ID = "01LOCKORG" as OrgId;

function subscription(overrides: Partial<Subscription>): Subscription {
  return {
    id: "01LOCKSUB" as SubscriptionId,
    orgId: ORG_ID,
    plan: "growth",
    interval: "monthly",
    status: "active",
    seats: 5,
    currentPeriodStart: EARLIER,
    currentPeriodEnd: LATER,
    cancelAt: null,
    createdAt: EARLIER,
    updatedAt: EARLIER,
    ...overrides,
  };
}

describe("lib/billing-lock", () => {
  // A workspace with no subscription row has nothing to be out of good standing about.
  it("treats a workspace with no subscription row as writable", () => {
    expect(lockReasonFor(null, NOW)).toBeNull();
  });

  // Only an active subscription is in good standing, whatever its dates say.
  it("keeps an active subscription writable even past its period end", () => {
    expect(
      lockReasonFor(subscription({ status: "active", currentPeriodEnd: EARLIER }), NOW),
    ).toBeNull();
  });

  // past_due has no grace date: the lock applies at once.
  it("locks a past-due subscription at once", () => {
    expect(lockReasonFor(subscription({ status: "past_due" }), NOW)).toBe(
      "past_due",
    );
  });

  // A trial stays writable until its period end is reached, then it locks.
  it("locks a trial from the moment its period end is reached", () => {
    const trial = subscription({ status: "trialing", currentPeriodEnd: LATER });
    expect(lockReasonFor(trial, NOW)).toBeNull();

    const endsNow = subscription({
      status: "trialing",
      currentPeriodEnd: toIsoTimestamp(NOW),
    });
    expect(lockReasonFor(endsNow, NOW)).toBe("trial_ended");
    expect(
      lockReasonFor(subscription({ status: "trialing", currentPeriodEnd: EARLIER }), NOW),
    ).toBe("trial_ended");
  });

  // A cancellation scheduled for later leaves the workspace writable until then.
  it("keeps a canceled subscription writable until its cancellation date", () => {
    const scheduled = subscription({ status: "canceled", cancelAt: LATER });
    expect(lockReasonFor(scheduled, NOW)).toBeNull();

    const reached = subscription({
      status: "canceled",
      cancelAt: toIsoTimestamp(NOW),
    });
    expect(lockReasonFor(reached, NOW)).toBe("canceled");
  });

  // A canceled subscription with no date is canceled now.
  it("locks a canceled subscription with no date at once", () => {
    expect(
      lockReasonFor(subscription({ status: "canceled", cancelAt: null }), NOW),
