beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

function setSubscription(orgId: OrgId, patch: SubscriptionPatch): void {
  getDb()
    .update(subscriptions)
    .set(patch)
    .where(eq(subscriptions.orgId, orgId))
    .run();
}

describe("services/workspace write lock", () => {
  // A refused create throws the lock and leaves no issue behind.
  it("refuses a create while past due, and writes nothing", async () => {
    const tenant = await createTenant("lock-past-due", "growth");
    setSubscription(tenant.org.id, { status: "past_due" });

    const attempt = issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Refused while locked" }),
    );

    await expect(attempt).rejects.toBeInstanceOf(WorkspaceLockedError);
    await expect(attempt).rejects.toMatchObject({ reason: "past_due" });

    const page = await issueRepo.listIssues({
      orgId: tenant.org.id,
      limit: 100,
      cursor: null,
    });
    expect(page.items.map((issue) => issue.title)).not.toContain(
      "Refused while locked",
    );
  });

  // Reads stay open, and the summaries report the lock for the shell banner.
  it("keeps reads and billing open, and reports the lock on the summaries", async () => {
    const tenant = await createTenant("lock-reads", "growth");
    setSubscription(tenant.org.id, { status: "past_due" });

    await expect(
      projectService.getProject(tenant.actors.owner, tenant.org.id, tenant.project.slug),
    ).resolves.toMatchObject({ project: { id: tenant.project.id } });
    await expect(
      organizationService.getOrganizationSummary(tenant.actors.owner, tenant.org.id),
    ).resolves.toMatchObject({ lockReason: "past_due" });
    await expect(
      billingService.getBillingSummary(tenant.actors.owner, tenant.org.id),
    ).resolves.toMatchObject({ lockReason: "past_due" });
  });

  // A successful plan change makes the workspace writable again.
  it("reopens writes once a plan is chosen", async () => {
    const tenant = await createTenant("lock-plan-change", "growth");
    setSubscription(tenant.org.id, { status: "past_due" });

    await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "enterprise",
      interval: "monthly",
    });

    await expect(
      issueService.createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, tenant.project.id, { title: "Written after upgrade" }),
      ),
    ).resolves.toMatchObject({ title: "Written after upgrade" });
  });

  // A trial is writable up to its period end and locked from that moment on.
  it("locks a trial from the moment its period end is reached", async () => {
    const tenant = await createTenant("lock-trial", "growth");
    const periodEnd = new Date("2026-06-01T00:00:00.000Z");
    setSubscription(tenant.org.id, {
      currentPeriodEnd: toIsoTimestamp(periodEnd),
    });

    await expect(
      billingService.assertWorkspaceWritable(
        tenant.org.id,
        new Date(periodEnd.getTime() - 1),
      ),
    ).resolves.toBeUndefined();
    await expect(
      billingService.assertWorkspaceWritable(tenant.org.id, periodEnd),
    ).rejects.toMatchObject({ reason: "trial_ended" });
  });

  // A cancellation scheduled for later keeps the workspace writable until it arrives.
  it("keeps a canceled workspace writable until its cancellation date", async () => {
    const tenant = await createTenant("lock-cancel", "growth");
    const cancelAt = new Date("2026-06-01T00:00:00.000Z");
    setSubscription(tenant.org.id, {
      status: "canceled",
      cancelAt: toIsoTimestamp(cancelAt),
    });

    await expect(
      billingService.assertWorkspaceWritable(
        tenant.org.id,
        new Date(cancelAt.getTime() - 1),
      ),
    ).resolves.toBeUndefined();
    await expect(
      billingService.assertWorkspaceWritable(tenant.org.id, cancelAt),
    ).rejects.toMatchObject({ reason: "canceled" });
  });

  // The pending invitation stays pending and no membership is created.
  it("refuses accepting an invitation into a locked workspace", async () => {
    const tenant = await createTenant("lock-invite", "growth");
    const rawToken = "c".repeat(32);
    const email = "locked-invitee@lock-invite.test";

    await invitationRepo.insertInvitation(
      tenant.org.id,
      { orgId: tenant.org.id, email, role: "member", expiresInDays: 14 },
      tenant.userIds.admin,
      hashToken(rawToken),
    );
    const invitee = await userRepo.insertUser({
      email,
      name: "Locked invitee",
      passwordHash: "seed",
    });
    setSubscription(tenant.org.id, { status: "past_due" });

    await expect(
      invitationService.acceptInvitation(invitee.id, { token: rawToken }),
    ).rejects.toBeInstanceOf(WorkspaceLockedError);
    await expect(
      memberRepo.findMember(tenant.org.id, invitee.id),
    ).resolves.toBeNull();
    await expect(
      invitationRepo.findInvitationByTokenHash(hashToken(rawToken)),
    ).resolves.toMatchObject({ acceptedAt: null });
  });

  // A caller refused by the permission matrix still sees that refusal, not the lock.
  it("gives an unauthorised caller the permission refusal, not the lock", async () => {
    const tenant = await createTenant("lock-order", "growth");
    setSubscription(tenant.org.id, { status: "past_due" });

    await expect(
      invitationService.inviteMember(tenant.actors.member, {
        orgId: tenant.org.id,
        email: "unwanted@lock-order.test",
        role: "member",
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });
});
